"""Render the public wire vocabulary from its sole shipped authority."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BEGIN = "<!-- connection-contract:begin -->"
END = "<!-- connection-contract:end -->"


def render():
    contract = json.loads((ROOT / "src/bat_agent_connector/connection_contract.json").read_text())
    lines = [
        BEGIN,
        "",
        "This block is generated by `scripts/generate_connection_contract.py --write`.",
        "此區塊由共用 JSON 產生；不得另行維護詞彙清單。",
        "",
        f"Contract version: **{contract['contract_version']}**; generator versions: "
        + ", ".join(map(str, contract["generator_versions"]))
        + ".",
        "",
        "Required artifact order / 必填產物順序: "
        + ", ".join("`" + role + "`" for role in contract["roles"])
        + ".",
        "",
        "Observations / 觀察值: " + ", ".join("`" + item + "`" for item in contract["observations"]) + ".",
        "",
        "| Outcome / 結果 | Phase / 階段 | Code / 代碼 |",
        "| --- | --- | --- |",
    ]
    for outcome, phases in contract["matrix"].items():
        for phase, codes in phases.items():
            values = ", ".join("`" + str(code) + "`" if code is not None else "`null`" for code in codes)
            lines.append(f"| `{outcome}` | `{phase}` | {values} |")
    lines += [
        "",
        "Closed code reasons / 封閉代碼與理由:",
        "",
        "| Code | English / 繁體中文 |",
        "| --- | --- |",
    ]
    for code, value in contract["codes"].items():
        lines.append(f"| `{code}` | {value['reason']} |")
    lines += ["", "| Bound / 限制 | Value / 值 |", "| --- | --- |"]
    for key, value in contract["bounds"].items():
        lines.append(f"| `{key}` | {value} |")
    return "\n".join([*lines, "", END])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true")
    args = parser.parse_args()
    path = ROOT / "docs/design/fleet-configuration.md"
    text = path.read_text()
    expected = text[: text.index(BEGIN)] + render() + text[text.index(END) + len(END) :]
    if args.write:
        path.write_text(expected)
    elif text != expected:
        raise SystemExit("Connection contract documentation differs; run with --write")


if __name__ == "__main__":
    main()
